use std::cell::RefCell;
use std::collections::HashMap;

thread_local! {
    static CACHE: RefCell<HashMap<String, usize>> = RefCell::new(HashMap::new());
}

pub fn touch(section: &str) {
    CACHE.with(|c| {
        let mut c = c.borrow_mut();
        *c.entry(section.to_string()).or_insert(0) += 1;
    });
}

pub fn hits(section: &str) -> usize {
    CACHE.with(|c| *c.borrow().get(section).unwrap_or(&0))
}

